input.query:
select p.proname, p.provolatile, pg_get_functiondef(p.oid) as tanim
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public' and p.proname = 'tr_kucuk';

create extension if not exists pg_trgm with schema extensions;
create index if not exists mekanlar_ad_trgm_idx
  on public.mekanlar using gin (public.tr_kucuk(ad) extensions.gin_trgm_ops);
select pg_size_pretty(pg_relation_size('public.mekanlar_ad_trgm_idx')) as indeks_boyutu,
       pg_size_pretty(pg_database_size(current_database())) as veritabani;

