import { fotografYukle } from '../../lib/fotograf-yukle'
import { checkinFotografYukle } from '../../lib/checkin-fotograf-yukle'
import { supabase } from '../../lib/supabase'

// Gercek cihazda dosya `File` sinifiyla okunuyor (SDK 54+ API'si);
// eski readAsStringAsync kaldirildi ve cihazda patliyordu.
const mockArrayBuffer = jest.fn()
jest.mock('expo-file-system', () => ({
  File: jest.fn().mockImplementation(() => ({ arrayBuffer: mockArrayBuffer })),
}))

const mockUpload = jest.fn()
jest.mock('../../lib/supabase', () => ({
  supabase: { storage: { from: jest.fn(() => ({ upload: mockUpload })) } },
}))

const BAYTLAR = new Uint8Array([1, 2, 3]).buffer

beforeEach(() => {
  jest.clearAllMocks()
  mockArrayBuffer.mockResolvedValue(BAYTLAR)
  mockUpload.mockResolvedValue({ data: { path: 'kullanici-1/123.jpg' }, error: null })
})

describe('fotograf yukleme (native)', () => {
  it('profil fotografini File API ile okuyup ham baytlarla yukler', async () => {
    const yol = await fotografYukle('kullanici-1', 'file:///tmp/foto.jpg')

    const { File } = jest.requireMock('expo-file-system')
    expect(File).toHaveBeenCalledWith('file:///tmp/foto.jpg')
    expect(supabase.storage.from).toHaveBeenCalledWith('profil-fotograflari')
    expect(mockUpload).toHaveBeenCalledWith(
      expect.stringMatching(/^kullanici-1\/\d+\.jpg$/),
      BAYTLAR,
      { contentType: 'image/jpeg' }
    )
    expect(yol).toBe('kullanici-1/123.jpg')
  })

  it('check-in fotografi ayni yolu kullanir, kendi kovasina yazar', async () => {
    await checkinFotografYukle('kullanici-1', 'file:///tmp/foto.jpg')

    expect(supabase.storage.from).toHaveBeenCalledWith('check-in-fotograflari')
    expect(mockUpload).toHaveBeenCalledWith(expect.any(String), BAYTLAR, {
      contentType: 'image/jpeg',
    })
  })

  it('yukleme hatasini oldugu gibi firlatir', async () => {
    mockUpload.mockResolvedValue({ data: null, error: new Error('Kova yok') })

    await expect(fotografYukle('kullanici-1', 'file:///tmp/foto.jpg')).rejects.toThrow('Kova yok')
  })
})

